DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.set_unit_status(uuid,public.unit_leasing_status,text,text,uuid)'::regprocedure) INTO d;d:=replace(d,'r:=public._assert_reason(reason);','IF new_status IS NULL OR nullif(btrim(ref_type),'''') IS NULL THEN RAISE EXCEPTION ''الحالة ونوع المرجع مطلوبان''; END IF; r:=public._assert_reason(reason);');d:=replace(d,'WHERE user_id=actor ORDER BY','WHERE user_id=actor AND is_active ORDER BY');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public._safety_audit(_action text,_table text,_id text,_before jsonb,_after jsonb,_reason text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.audit_log(actor_id,actor_email,actor_role,action,entity_table,entity_id,before_data,after_data,context) VALUES(auth.uid(),(SELECT email FROM public.profiles WHERE user_id=auth.uid() LIMIT 1),(SELECT role::text FROM public.user_roles WHERE user_id=auth.uid() AND is_active ORDER BY CASE WHEN role='admin' THEN 0 ELSE 1 END LIMIT 1),_action,_table,_id,_before,_after,jsonb_build_object('reason',_reason,'operation',lower(_action)));$$;
SELECT has_column_privilege('authenticated','public.units','status','UPDATE') AS old_status_must_be_false,has_column_privilege('authenticated','public.units','leasing_status','UPDATE') AS new_status_must_be_false;
SELECT hold_hours,max_hold_extensions FROM public.app_settings WHERE id=1;